$talkpik_wireframe_problem_seed_20260608120200$::jsonb) as seed(row_data)
), deduped_seed_rows as (
  select distinct on (
    row_data->'materials'->>'source_file',
    row_data->'materials'->>'source_item_id'
  ) row_data
  from seed_rows
  order by
    row_data->'materials'->>'source_file',
    row_data->'materials'->>'source_item_id'
)
insert into public.problems (
  source,
  author_id,
  domain,
  question_no,
  topik_level,
  difficulty,
  title,
  prompt,
  materials,
  answer_key,
  rubric,
  explanation,
  tags,
  publish_status,
  review_status,
  visibility
)
select
  row_data->>'source' as source,
  null::uuid as author_id,
  row_data->>'domain' as domain,
  (row_data->>'question_no')::smallint as question_no,
  (row_data->>'topik_level')::smallint as topik_level,
  case
    when jsonb_typeof(row_data->'difficulty') = 'number'
      then (row_data->>'difficulty')::smallint
    else null::smallint
  end as difficulty,
  row_data->>'title' as title,
  row_data->>'prompt' as prompt,
  row_data->'materials' as materials,
  row_data->'answer_key' as answer_key,
  row_data->'rubric' as rubric,
  row_data->>'explanation' as explanation,
  array(
    select tag
    from jsonb_array_elements_text(row_data->'tags') as source_tags(tag)
  ) as tags,
  row_data->>'publish_status' as publish_status,
  row_data->>'review_status' as review_status,
  row_data->>'visibility' as visibility
from deduped_seed_rows
where not exists (
  select 1
  from public.problems existing
  where existing.materials->>'seed_source' = 'wireframe_problem_fixtures'
    and existing.materials->>'source_file' = deduped_seed_rows.row_data->'materials'->>'source_file'
    and existing.materials->>'source_item_id' = deduped_seed_rows.row_data->'materials'->>'source_item_id'
);
